/**
 * The project's shared framework Transients store, prefixed so its keys can
 * never collide with another consumer's.
 *
 * @return \rtCamp\WPFramework\Utils\Transients Shared transients store.
 */
public static function transients(): \rtCamp\WPFramework\Utils\Transients {
	static $instance = null;

	if ( null === $instance ) {
		$instance = new \rtCamp\WPFramework\Utils\Transients( '{{context_slug}}' );
	}

	return $instance;
}
